import{_ as e,a as d}from"./chunks/21-cli-validate.ButpL1-4.js";import{_ as o,o as r,c,a2 as a}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"سطر الأوامر","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/command-line.md","filePath":"ar/guide/command-line.md"}'),l={name:"ar/guide/command-line.md"};function i(n,t,s,E,g,m){return r(),c("div",null,[...t[0]||(t[0]=[a('<h1 id="سطر-الأوامر" tabindex="-1">سطر الأوامر <a class="header-anchor" href="#سطر-الأوامر" aria-label="Permalink to &quot;سطر الأوامر&quot;">​</a></h1><p>على Windows استخدم <code>reelforge.cmd</code>، وعلى macOS وLinux استخدم <code>./reelforge</code> (أو أضف المجلد إلى PATH). ومن نسخة المصدر يعمل <code>pnpm reelforge</code> على كل الأنظمة. تجد كل أمر وكل خيار في <a href="./../reference/cli.html">مرجع CLI</a> المولّد من تعريف الأوامر نفسه.</p><p><img src="'+e+'" alt="مساعدة سطر الأوامر"></p><h2 id="الأوامر-الأساسية" tabindex="-1">الأوامر الأساسية <a class="header-anchor" href="#الأوامر-الأساسية" aria-label="Permalink to &quot;الأوامر الأساسية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الأمر</th><th>الوصف</th></tr></thead><tbody><tr><td><code>reelforge studio [--port &lt;n&gt;] [--host &lt;address&gt;] [--no-open]</code></td><td>فتح لوحة التحكم (الافتراضي <code>http://127.0.0.1:4310</code>)</td></tr><tr><td><code>reelforge new &lt;id&gt; [--series &lt;name&gt;] [--episode &lt;n&gt;] [--lang en|ar]</code></td><td>إنشاء <code>episodes/&lt;id&gt;/episode.yaml</code> من القالب الفارغ المشروح</td></tr><tr><td><code>reelforge new &lt;id&gt; --pack &lt;pack&gt; [--template &lt;t&gt;] [--lang ar] [--slot k=v …]</code></td><td>إنشاؤها من قالب قطاعي مع cues تقديرية (راجع <a href="./templates-and-packs.html">القوالب</a>)</td></tr><tr><td><code>reelforge packs [--lang en|ar]</code></td><td>عرض الحزم القطاعية وقوالبها وحقولها (<code>--json</code> للتفاصيل الكاملة)</td></tr><tr><td><code>reelforge edit &lt;id&gt;</code></td><td>فتح المحرر المرئي</td></tr><tr><td><code>reelforge cue &lt;id&gt; [--draft]</code></td><td>فتح المحرر في وضع Cues (يكتب <code>--draft</code> cues تقديرية بدلاً من ذلك)</td></tr><tr><td><code>reelforge align &lt;id&gt; [--engine dsp|whisper] [--force] [--dry-run]</code></td><td>تحديد الـ cues لكل سطر وكل كلمة من التسجيل (راجع <a href="./timing.html">التوقيت</a>)</td></tr><tr><td><code>reelforge align --setup [--model tiny|base|small]</code> / <code>--status</code></td><td>تثبيت نماذج الكلام الاختيارية أو عرض حالتها (مرة واحدة، ~180 MB)</td></tr><tr><td><code>reelforge dev &lt;id&gt;</code></td><td>فتح المحرر في وضع Review</td></tr><tr><td><code>reelforge mcp [--toolsets basic,design,render]</code></td><td>تشغيل خادم MCP لمساعدي الذكاء الاصطناعي (راجع <a href="./ai.html">التكامل مع الذكاء الاصطناعي</a>)</td></tr><tr><td><code>reelforge validate &lt;id&gt; [--strict] [--no-measure]</code></td><td>فحص كل شيء؛ رمز الخروج 1 عند الأخطاء (أو التحذيرات مع <code>--strict</code>)</td></tr><tr><td><code>reelforge render &lt;id&gt; [options]</code> / <code>--all</code></td><td>التصدير (راجع <a href="./rendering.html">التصدير والنشر</a>)</td></tr><tr><td><code>reelforge snap &lt;id&gt; &lt;times…&gt; [--every 5] [--cover]</code></td><td>صور PNG وورقة لقطات؛ الأزمنة مثل <code>12.5</code> و<code>l7</code> و<code>&quot;l7:&#39;word&#39;&quot;</code></td></tr><tr><td><code>reelforge doctor [--fix]</code></td><td>فحص البيئة؛ ومع <code>--fix</code> يُنزّل Chromium</td></tr><tr><td><code>reelforge theme new &lt;name&gt; --accent &lt;#hex&gt; [--mode light|dark] [--font &lt;f&gt;]</code></td><td>توليد ثيم كامل (بتباين مفحوص) من لون تمييز واحد</td></tr><tr><td><code>reelforge schema [--out &lt;file&gt;]</code></td><td>كتابة JSON Schema للإكمال التلقائي في المحررات</td></tr></tbody></table><p>الخيارات العامة: <code>--json</code> (مخرجات قابلة للقراءة الآلية، وأحداث تقدم أثناء التصدير)، و<code>--verbose</code>، و<code>--root &lt;folder&gt;</code> (مجلد المشروع؛ الافتراضي هو المجلد الحالي).</p><p><img src="'+d+'" alt="الأمر validate"></p><p>خيارات الأمر <code>reelforge align</code>: ‏<code>--engine auto|dsp|whisper</code> (القيمة auto تستخدم Whisper إن كان مثبّتاً، وإلا فكشف الوقفات)، و<code>--model tiny|base|small</code>، و<code>--no-vad</code>، و<code>--no-words</code> (cues الأسطر فقط)، و<code>--force</code> (استبدال الـ cues التي حددتها يدوياً)، و<code>--dry-run</code> (طباعة النتيجة دون كتابتها). ويتجاوز الخياران <code>reelforge render --denoise</code> و<code>--no-denoise</code> قيمة <code>audio.denoise</code>.</p><h2 id="متغيرات-البيئة" tabindex="-1">متغيرات البيئة <a class="header-anchor" href="#متغيرات-البيئة" aria-label="Permalink to &quot;متغيرات البيئة&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المتغير</th><th>المعنى</th></tr></thead><tbody><tr><td><code>REELFORGE_ROOT</code></td><td>مجلد المشروع</td></tr><tr><td><code>REELFORGE_PRESET</code></td><td>الـ preset الافتراضي</td></tr><tr><td><code>REELFORGE_WORKERS</code></td><td>عدد عمليات التصدير</td></tr><tr><td><code>REELFORGE_SHARE_SIZE</code></td><td>حجم ملف النشر بالميغابايت</td></tr><tr><td><code>REELFORGE_JPEG_QUALITY</code></td><td>جودة التقاط الإطارات (الافتراضي 95)</td></tr><tr><td><code>REELFORGE_PORT</code></td><td>منفذ لوحة التحكم أو المحرر</td></tr><tr><td><code>REELFORGE_HOST</code></td><td>عنوان ربط لوحة التحكم (الافتراضي 127.0.0.1)</td></tr><tr><td><code>REELFORGE_ALLOWED_HOSTS</code></td><td>أسماء Host إضافية تقبلها لوحة التحكم (مفصولة بفواصل)</td></tr><tr><td><code>REELFORGE_REQUIRE_TOKEN</code></td><td>القيمة <code>1</code> تشترط الـ token على <code>/mcp</code> و<code>/api/v1</code> في كل الحالات</td></tr><tr><td><code>REELFORGE_NO_OPEN</code></td><td>عدم فتح المتصفح تلقائياً</td></tr><tr><td><code>REELFORGE_FFMPEG</code> و<code>REELFORGE_FFPROBE</code></td><td>مسارا ffmpeg وffprobe</td></tr><tr><td><code>REELFORGE_CHROMIUM</code></td><td>مسار ملف Chromium التنفيذي</td></tr><tr><td><code>REELFORGE_CACHE</code></td><td>مجلد نماذج الكلام الاختيارية</td></tr><tr><td><code>REELFORGE_CONFIG_DIR</code></td><td>مجلد الإعدادات (<code>llm.json</code> والـ token)</td></tr><tr><td><code>REELFORGE_LLM_*</code></td><td>النموذج اللغوي لاقتراح المشاهد (راجع <a href="./ai.html#models">النماذج</a>)</td></tr><tr><td><code>NO_COLOR</code></td><td>إيقاف الألوان</td></tr></tbody></table>',10)])])}const _=o(l,[["render",i]]);export{p as __pageData,_ as default};
